import os,re,subprocess
roots=set()
for l in open('AlgebraicJacobian.lean'):
    m=re.match(r'\s*import\s+(\S+)',l)
    if m: roots.add(m.group(1))
mods={}
for dp,_,fs in os.walk('AlgebraicJacobian'):
    for f in fs:
        if f.endswith('.lean'):
            p=os.path.join(dp,f)
            mods[p[:-5].replace('/','.')]=p
# transitive closure of imports from roots
imports={}
for m,p in mods.items():
    imports[m]=[x.group(1) for x in re.finditer(r'(?m)^\s*import\s+(\S+)',open(p).read())]
seen=set()
stack=list(roots)
while stack:
    m=stack.pop()
    if m in seen or m not in imports: continue
    seen.add(m)
    stack.extend(imports[m])
unreach=sorted(m for m in mods if m not in seen)
print('modules NOT reachable from the umbrella at all:', len(unreach))
noolean=[m for m in unreach if not os.path.exists('.lake/build/lib/lean/'+m.replace('.','/')+'.olean')]
print('of those, never built (no olean):', len(noolean))
for m in noolean: print('   UNMEASURED:', m)
